  ];
  var RULE_AGE = 59.5, MIN_YEARS = 5;   // IRC 72(t)(4): 5 years or age 59 1/2, whichever is later
  var SAFE_HARBOR_RATE = 5;             // Notice 2022-6 s. 3.02(c)
  var EARLY_PENALTY = 0.10;             // IRC 72(t)(1)
  var RMD_AGE = 75;                     // IRC 401(a)(9)(C)(v): born 1960 or later (everyone aged 59 or less in 2026)
  var LAST_AGE = 100;
  // ----------------------------------------------------------------------------------------------------

  function singleLE(a) { return SINGLE[Math.min(Math.max(a, 0), 120)]; }
  function uniformLE(a) { return UNIFORM[Math.min(Math.max(a, UNIFORM_FROM), 120) - UNIFORM_FROM]; }
  function jointLE(o, b) {
    var row = JOINT[Math.min(o, JOINT_FROM + JOINT.length - 1) - JOINT_FROM];
    var k = Math.min(Math.max(b, 0), 120) * 2;
    return parseInt(row.substr(k, 2), 36) / 10;
  }
  function lifeExpectancy(table, o, b) {
    if (table === 'joint') return jointLE(o, b);
    if (table === 'uniform') return uniformLE(o);
    return singleLE(o);
  }
  function survival(x) {
    var p = [1];
    for (var a = x; a <= 120; a++) p.push(p[p.length - 1] * (1 - MORTALITY[a]));
    return p;
  }
  function annuityFactor(x, y, i, joint) {
    var px = survival(x), py = joint ? survival(y) : [], n = Math.max(px.length, py.length), s = 0;
    for (var k = 1; k < n; k++) {
      var a = k < px.length ? px[k] : 0, b = joint && k < py.length ? py[k] : 0;
      s += (joint ? a + b - a * b : a) / Math.pow(1 + i, k);
    }
    return s;
  }
  function amortFactor(n, i) { return i === 0 ? n : (1 - Math.pow(1 + i, -n)) / i; }
  function fixedPayment(p) {
    if (p.method === 'annuity') return p.balance / annuityFactor(p.age, p.benAge, p.rate, p.table === 'joint');
    return p.balance / amortFactor(lifeExpectancy(p.table, p.age, p.benAge), p.rate);
  }

  // p: balance, age, benAge, table, method, rate, growth, after, tax (decimals)
  function simulate(p, withSepp) {
    var years = Math.max(MIN_YEARS, Math.ceil(RULE_AGE - p.age));
    var fixed = fixedPayment(p), bal = p.balance, rows = [], total = 0, early = 0, lastAge = NaN, seppDepleted = false, endBal = NaN;
    for (var y = 0; p.age + y <= LAST_AGE; y++) {
      var a = p.age + y, start = bal, pay = 0;
      if (bal <= 0) { rows.push({ age: a, pay: 0, bal: 0, sepp: y < years }); if (y === years - 1) endBal = 0; continue; }
      if (y < years) {
        if (withSepp) pay = p.method === 'rmd' ? start / lifeExpectancy(p.table, a, p.benAge + y) : fixed;
      } else {
        pay = Math.max(p.after, a >= RMD_AGE ? start / uniformLE(a) : 0);
      }
      var grown = start * (1 + p.growth);
      if (pay >= grown) { pay = grown; if (y < years && withSepp) seppDepleted = true; }
      bal = grown - pay;
      if (bal < 0.005) { bal = 0; lastAge = a; }
      if (y < years && withSepp) { total += pay; if (a < 60) early += pay; }
      if (y === years - 1) endBal = bal;
      rows.push({ age: a, pay: pay, bal: bal, sepp: y < years });
