    var w = simulate(p, true), wo = simulate(p, false);
    var first = w.rows[0].pay;
    set('diPayment', fmt(first));
    set('diPaymentNote', fmt(first / 12) + ' a month' + (method === 'rmd' ? ', recalculated each year' : ', the same every year'));
    set('diCost', fmt(wo.endBal - w.endBal));
    set('diCostNote', 'Less in the account at age ' + (age + w.years - 1) + ' than if you left it alone');
    set('diLastWith', lastText(w));
    set('diLastWithout', lastText(wo));
    set('diEnd', 'Age ' + ageText(w.endAge) + ' – ' + w.years + ' annual payments');
    set('diTotal', fmt(w.total));
    set('diIncomeTax', fmt(w.total * p.tax));
    set('diAvoided', fmt(w.early * EARLY_PENALTY));
    set('diBalWith', fmt(w.endBal));
    set('diBalWithout', fmt(wo.endBal));
    var box = document.getElementById('diBreakBox');
    box.hidden = brk === 0;
    if (brk > 0) {
      if (brk > w.years) {
        set('diBreakTitle', 'If the payments change in year ' + brk);
        set('diRecapture', '$0'); set('diInterest', '$0'); set('diRecaptureTotal', '$0');
        set('diBreakNote', 'Year ' + brk + ' is after the 72(t) period ends, so you can change or stop the payments freely.');
      } else {
        var rc = recapture(w.rows, brk, irsRate / 100);
        set('diBreakTitle', 'If the payments change in year ' + brk + ' (age ' + (age + brk - 1) + ')');
        set('diRecapture', fmt(rc.tax));
        set('diInterest', fmt(rc.interest));
        set('diRecaptureTotal', fmt(rc.tax + rc.interest));
        set('diBreakNote', 'The 10% comes back on every earlier payment taken before 59½' +
            (age + brk - 1 < 60 ? ', and whatever you withdraw in year ' + brk + ' also owes the 10% as a normal early withdrawal.' : '.') +
            ' Death, disability or the account running out aren’t treated as changes.');
      }
    }
    var rateNote = document.getElementById('diRateNote');
    rateNote.hidden = !(rate > SAFE_HARBOR_RATE);
    if (rate > SAFE_HARBOR_RATE) set('diRateNote', 'A rate above ' + SAFE_HARBOR_RATE + '% is allowed only if 120% of the federal mid-term rate ' +
        'for either of the two months before your first payment is at least that high.');
    var dep = document.getElementById('diDepleted');
    dep.hidden = !w.seppDepleted;
    if (w.seppDepleted) set('diDepleted', 'At this return the 72(t) payments empty the account before they can stop. Running out ' +
        'isn’t a change to the schedule, so no 10% is recaptured.');
    var body = document.getElementById('diSchedule');
    body.textContent = '';
    w.rows.forEach(function (row, i) {
      var o = wo.rows[i];
      var tr = document.createElement('tr');
      [row.age + (row.sepp ? ' (72(t))' : ''), fmt(row.pay), fmt(row.bal), fmt(o.pay), fmt(o.bal), fmt(row.bal - o.bal)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

